import { createI18n } from 'vue-i18n'
import { en, type MessageKey } from './locales/en'
import { zhCN } from './locales/zh-CN'

const messages = { en, 'zh-CN': zhCN }
export type Locale = keyof typeof messages
export type { MessageKey } from './locales/en'
const STORAGE_KEY = 'bui-locale'
function initialLocale(): Locale {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)
    if (saved && Object.hasOwn(messages, saved)) return saved as Locale
  } catch { /* Storage can be disabled. */ }
  const preferred = typeof navigator === 'undefined' ? 'en' : navigator.language.toLowerCase()
  const supported = Object.keys(messages) as Locale[]
  return supported.find(code => code.toLowerCase() === preferred)
    ?? supported.find(code => code.split('-')[0] === preferred.split('-')[0])
    ?? 'en'
}

// The same Composer also serves standalone registry components without app injection.
export const i18n = createI18n({
  legacy: false,
  globalInjection: false,
  locale: initialLocale(),
  fallbackLocale: 'en',
  messages,
})
export const locale = i18n.global.locale
export function setLocale(next: Locale) {
  locale.value = next
  try { localStorage.setItem(STORAGE_KEY, next) } catch { /* Keep switching usable without storage. */ }
}

/** Stable keys for new UI copy. Params are literal data, never translated implicitly. */
export function t(key: MessageKey, params: Record<string, unknown> | unknown[] | number = {}, options: { locale?: Locale } = {}) {
  if (typeof params === 'number') return i18n.global.t(key, params, options)
  if (Array.isArray(params)) return i18n.global.t(key, params, options)
  return i18n.global.t(key, params, options)
}

import { computed, defineComponent, h, onBeforeUnmount, onMounted, shallowRef, Teleport, watch, type Component, type FunctionalComponent, type ShallowRef, type VNodeChild, type Slots, type CSSProperties, type PropType } from 'vue'

/** Declare actual Vue props and execute initialization exactly once per instance. */
export function createComponent<P>(name: string, keys: string[], setup: (props: P, slots: Slots) => () => VNodeChild, propTypes: Partial<Record<Extract<keyof P, string>, PropType<unknown>>> = {}): FunctionalComponent<Omit<P, "children"> & { children?: VNodeChild }> {
  // Explicit undefined preserves defaults resolved by the component setup.
  const types: Record<string, PropType<unknown>> = { disabled: Boolean, ...propTypes }
  return defineComponent({
    name,
    inheritAttrs: false,
    props: Object.fromEntries([...new Set([...keys, 'children', 'disabled', 'type', 'title', 'id', 'onClick', 'onPointerdown', 'onPointerup', 'onFocus', 'onBlur', 'aria-label', 'aria-expanded', 'aria-pressed', 'data-sound'])].map(key => [key, types[key] ? { type: types[key], default: undefined } : {}])),
    setup(props, { slots, attrs }) {
      const all = new Proxy(props, {
        get: (target, key) => key in target ? Reflect.get(target, key) : attrs[key as string],
        ownKeys: (target) => [...new Set([...Reflect.ownKeys(target), ...Reflect.ownKeys(attrs)])],
        getOwnPropertyDescriptor: () => ({ enumerable: true, configurable: true }),
      })
      return setup(all as P, slots)
    },
  }) as unknown as FunctionalComponent<Omit<P, "children"> & { children?: VNodeChild }>
}

export function createState<T>(initial: T | (() => T)): [ShallowRef<T>, (next: T | ((current: T) => T)) => void] {
  const state = shallowRef(typeof initial === 'function' ? (initial as () => T)() : initial) as ShallowRef<T>
  return [state, (next) => { state.value = typeof next === 'function' ? (next as (current: T) => T)(state.value) : next }]
}
export function templateRef<T>(initial: T): ShallowRef<T>;
export function templateRef<T>(initial: null): ShallowRef<T | null>;
export function templateRef<T>(initial: T | null): ShallowRef<T | null> { return shallowRef(initial) as ShallowRef<T | null> }

/** Effects run after DOM refs exist, rerun on declared reactive inputs, and dispose on unmount. */
export function watchLifecycle(effect: () => void | (() => void), sources: () => unknown[] = () => []) {
  let stop: (() => void) | undefined
  onMounted(() => {
    stop = watch(sources, (_value, _old, onCleanup) => {
      const cleanup = effect()
      if (typeof cleanup === 'function') onCleanup(cleanup)
    }, { immediate: true, flush: 'post' })
  })
  onBeforeUnmount(() => stop?.())
}

const unitless = new Set(['animationIterationCount', 'aspectRatio', 'borderImageOutset', 'borderImageSlice', 'borderImageWidth', 'columnCount', 'flex', 'flexGrow', 'flexShrink', 'fontWeight', 'gridArea', 'gridColumn', 'gridColumnEnd', 'gridColumnStart', 'gridRow', 'gridRowEnd', 'gridRowStart', 'lineHeight', 'opacity', 'order', 'orphans', 'scale', 'tabSize', 'widows', 'zIndex', 'zoom', 'fillOpacity', 'strokeDashoffset', 'strokeOpacity', 'strokeWidth'])
export function cssStyle(style: unknown): CSSProperties {
  if (!style || typeof style !== 'object') return style as CSSProperties
  return Object.fromEntries(Object.entries(style).map(([key, value]) => [key, typeof value === 'number' && value !== 0 && !key.startsWith('--') && !unitless.has(key) ? `${value}px` : value])) as CSSProperties
}
export function omitProps<P extends object>(props: P, names: string[]) { return Object.fromEntries(Object.entries(props).filter(([key]) => !names.includes(key))) }
export function teleport(children: VNodeChild, target: Element | string) { return h(Teleport, { to: target }, children as never) }

// Native Vue JSX. Design and behavior adapted from Beautiful UI (MIT).
import type * as UI from '@/lib/dom-types';
import { computed, type ComputedRef, type FunctionalComponent } from 'vue';
import { createComponent, createState, templateRef, watchLifecycle, cssStyle, omitProps, teleport } from '@/lib/vue-tools';
import type { VNodeChild } from '@/lib/dom-types';
type GlideMenuProps = {
  children: VNodeChild;
  className?: string;
  highlightClassName?: string;
  rowSelector?: string;
};

/** A single hover layer that glides between interactive menu rows. */
const GlideMenu = createComponent<GlideMenuProps>("GlideMenu", ["children", "className", "highlightClassName", "rowSelector"], (__props, __slots) => {
  const children = { get value() { return __slots.default?.() ?? __props.children; } };
  const className = computed(() => __props.className === undefined ? "" : __props.className);
  const highlightClassName = computed(() => __props.highlightClassName === undefined ? "inset-x-0 rounded-[8px] bg-hover" : __props.highlightClassName);
  const rowSelector = computed(() => __props.rowSelector === undefined ? "[data-menu-row]" : __props.rowSelector);
  const ref = templateRef<HTMLDivElement>(null);
  const [box, setBox] = createState<{
    top: number;
    height: number;
  } | null>(null);
  const [visible, setVisible] = createState(false);
  const moveTo = (target: EventTarget | null) => {
    const container = ref.value;
    if (!(target instanceof Element) || !container) return;
    const row = target.closest(rowSelector.value);
    if (!(row instanceof HTMLElement) || !container.contains(row)) return;
    const containerRect = container.getBoundingClientRect();
    const rowRect = row.getBoundingClientRect();
    setBox({
      top: rowRect.top - containerRect.top,
      height: rowRect.height
    });
    setVisible(true);
  };
  return () => {
    return <div ref={ref} onMouseover={event => moveTo(event.target as HTMLInputElement)} onMouseleave={() => setVisible(false)} onFocusin={event => moveTo(event.target as HTMLInputElement)} onFocusout={event => {
      if (!ref.value?.contains(event.relatedTarget as Node | null)) setVisible(false);
    }} class={`group/glide-menu relative ${className.value}`}>
      <span aria-hidden class={`pointer-events-none absolute ${highlightClassName.value}`} style={cssStyle({
        top: box.value?.top ?? 0,
        height: box.value?.height ?? 0,
        opacity: box.value && visible.value ? 1 : 0,
        transition: "top 220ms cubic-bezier(0.23,1,0.32,1), height 220ms cubic-bezier(0.23,1,0.32,1), opacity 150ms ease"
      })} />
      {children.value}
    </div>;
  };
});
export default GlideMenu;

@import "tailwindcss";
/* shadow-plugin (flornkm) — smooth, layered shadow stacks. The unprefixed
 * entry maps them onto Tailwind's --shadow-xs…2xl scale; our semantic tokens
 * below build on those values so the whole app picks up the smooth shadows. */
@import "shadow-plugin/unprefixed";

@custom-variant dark (&:where(.dark, .dark *));

/* GENERIC FOUNDATION — tokens, @theme, base rules, the primitive-*
 * spacing utilities, and shared keyframes below are needed by EVERY
 * component. Blocks tagged COMPONENT-SPECIFIC further down belong to
 * one primitive each. */
/* ──────────────────────────────────────────────────────────
 * Beautiful UI — design tokens
 * Cool near-white canvas, white cards, hairline borders, layered
 * single-digit-opacity shadows, a neutral ink ramp, and semantic
 * color used sparingly as a condiment.
 * ────────────────────────────────────────────────────────── */

:root {
  /* Native controls and all inherited scrollbars follow the active theme. */
  color-scheme: light;
  scrollbar-color: var(--line-strong) transparent;
  /* surfaces — cool, blue-tinted neutrals */
  --page: oklch(0.985 0.001 286.376);
  --canvas: oklch(0.961 0.002 247.84);
  --surface: oklch(1 0 0);
  --inset: oklch(0.979 0.002 247.839);
  --hover: oklch(0.97 0.002 247.839);
  --hover-2: oklch(0.933 0.003 247.86);

  /* ink ramp */
  --ink: oklch(0.247 0.006 258.361);
  --ink-2: oklch(0.506 0.01 264.477);
  --ink-3: oklch(0.695 0.009 264.505);

  /* borders — solid and crisp, not alpha */
  --line: oklch(0.946 0.003 264.542);
  --line-strong: oklch(0.912 0.005 258.326);
  --line-soft: oklch(0.966 0.002 264.542);
  --grid-line: color-mix(in srgb, var(--line) 78%, transparent);
  --field: oklch(0.961 0.001 286.375);
  --stripe: oklch(0.405 0 0 / 0.075);
  --stripe-bg: oklch(0.97 0 0);

  /* accent */
  --accent: oklch(0.626 0.205 254.947);
  --accent-ink: oklch(0.556 0.187 255.617);
  --accent-tint: oklch(0.96 0.019 252.878);

  /* semantic */
  --green: oklch(0.603 0.155 150.883);
  --green-tint: oklch(0.958 0.017 159.118);
  --orange: oklch(0.689 0.179 49.902);
  --orange-tint: oklch(0.964 0.021 67.581);
  --red: oklch(0.621 0.192 23.042);
  --red-tint: oklch(0.956 0.017 17.462);

  /* chart overlays — neutral system colors with enough contrast on either theme */
  --tooltip-bg: oklch(0.272 0.008 264.435);
  --tooltip-fg: oklch(0.976 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.356 0.007 264.474);

  /* shadows — our solid hairline ring + shadow-plugin's smooth layered stacks
   * (--shadow-xs…lg come from shadow-plugin/unprefixed) so every surface reads
   * consistently across the app. */
  --shadow-hairline: 0 0 0 1px var(--line);
  --shadow-btn: 0 0 0 1px var(--line-strong), var(--shadow-xs);
  --shadow-card: 0 0 0 1px var(--line), var(--shadow-sm);
  --shadow-raised: 0 0 0 1px var(--line), var(--shadow-md);
  --shadow-overlay: 0 0 0 1px var(--line), var(--shadow-lg);
  --shadow-inset-field: inset 0 1px 2px oklch(0 0 0 / 0.12);
}

.dark {
  color-scheme: dark;
  --page: oklch(0.209 0.004 264.477);
  --canvas: oklch(0.231 0.004 264.487);
  --surface: oklch(0.26 0.006 271.191);
  --inset: oklch(0.243 0.004 264.492);
  --hover: oklch(0.289 0.006 271.22);
  --hover-2: oklch(0.318 0.007 274.747);

  --ink: oklch(0.964 0.002 247.839);
  --ink-2: oklch(0.731 0.008 260.731);
  --ink-3: oklch(0.541 0.01 264.484);

  --line: oklch(0.308 0.006 258.354);
  --line-strong: oklch(0.356 0.007 264.474);
  --line-soft: oklch(0.278 0.006 258.354);
  --field: oklch(0.293 0.006 271.223);
  --stripe: oklch(1 0 0 / 0.055);
  --stripe-bg: oklch(0.226 0.004 264.485);

  --accent: oklch(0.68 0.173 253.301);
  --accent-ink: oklch(0.788 0.113 248.33);
  --accent-tint: oklch(0.68 0.173 253.301 / 0.16);

  --green: oklch(0.705 0.154 153.814);
  --green-tint: oklch(0.705 0.154 153.814 / 0.14);
  --orange: oklch(0.746 0.156 55.642);
  --orange-tint: oklch(0.746 0.156 55.642 / 0.14);
  --red: oklch(0.666 0.18 21.433);
  --red-tint: oklch(0.666 0.18 21.433 / 0.14);

  --tooltip-bg: oklch(0.182 0.004 264.459);
  --tooltip-fg: oklch(0.964 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.308 0.006 258.354);

  --shadow-hairline: 0 0 0 1px var(--line);
  /* Elevation rings go to a subtle *light* hairline in dark mode: the ring
